import React from 'react'
import { useGetYarnMasterQuery } from '../../../redux/ErpServices/YarnMasterServices';
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { useGetUnitOfMeasurementMasterQuery } from '../../../redux/ErpServices/UnitOfMeasurementServices';
import { Loader } from '../../../Basic/components';
import { VIEW } from '../../../icons';
import secureLocalStorage from 'react-secure-storage';
import { findFromList } from '../../../Utils/helper'
import { useGetFabricMasterQuery } from '../../../redux/ErpServices/FabricMasterServices';





const RawMaterialYarn = ({yarnData,yarnTotal,programDetails}) => {
  
const params = {
  companyId: secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userCompanyId"
  ),
};
  const { data: yarnList } =
  useGetYarnMasterQuery({ params });

  const { data: fabricList } =
  useGetFabricMasterQuery({ params });

const { data: colorList, isLoading: isColorLoading, isFetching: isColorFetching } =
  useGetColorMasterQuery({ params });

const { data: uomList } =
  useGetUnitOfMeasurementMasterQuery({ params });
  if (!yarnList || !colorList || !uomList) return <Loader />

 const array= function findArrayElementByTitle(programDetails, rawMaterials) {
    return programDetails.find((element) => {
      return element.rawMaterials === rawMaterials;
      console.log(array,"array")
    })
  }
  
  return (
    <div>
       <div className='w-full text-sm font-bold mt-3'>
        <h1>
          YARN RAW MATERIAL
        </h1>
      </div>
      <table className=" text-xs border border-gray-500 table-auto w-full ">
    <thead className=' border border-gray-500 top-0'>
        <tr className='h-8'>
            <th className="table-data  w-16 text-center">S.no</th>
            <th className="table-data text-center">YARN DESCRIPTION</th>
            <th className="table-data ">COLOR</th>
            <th className="table-data ">UOM</th>
            <th className="table-data  ">NO.OF.ROLLS</th>
            <th className="table-data  ">ISS.QTY</th>
         
            </tr>
          </thead>
          <tbody>
           {programDetails.map((value,valueIndex)=>
            (
              value.rawMaterials.map((item,itemIndex)=>
              (
<tr  className=' border border-gray-500 top-0'>
     <td className='table-data text-center px-1 h-8 '>{itemIndex+1}</td>
     <td className='table-data  px-1 h-8 '>{item.Yarn?.aliasName}</td>
     <td className='table-data  px-1 h-8 '>{item.Color?.name}</td>
     <td className='table-data  px-1 h-8 '>{item.Uom?.name}</td>
     <td className='table-data text-right px-1 h-8 '>{item.noOfBags}</td>
     <td className='table-data text-right px-1 h-8 '>{item.qty}</td>
  
      </tr>
              ))

 
  ))} 
             
<tr  className=' border border-gray-500 top-0'>
  <td className=' text-center  px-1 h-8 table-data' colSpan={5}>TOTAL</td>
   <td className='px-1 h-8 text-right'>{yarnTotal}</td> 
</tr>
 
          </tbody>
          </table>
    </div>
  )
}

export default RawMaterialYarn