import React, { useEffect, useState } from 'react'
import { useGetUnitOfMeasurementMasterQuery } from "../../../redux/ErpServices/UnitOfMeasurementServices";
import { Loader } from '../../../Basic/components';
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { findFromList, isBetweenRange, params, substract } from '../../../Utils/helper';
import {
  useGetSizeMasterQuery,
} from "../../../redux/ErpServices/SizeMasterServices";
import {
  useGetCuttingOrderQuery,
  useGetCuttingOrderByIdQuery,
} from "../../../redux/ErpServices/CuttingOrderServices";
import CuttingReceiptAlreadyReceivedQty from './CuttingReceiptAlreadyReceivedQty';
import { toast } from 'react-toastify';

const CuttingReceiptInwardDetails = ({ id, readOnly, cuttingOrderId, cuttingReceiptInwardDetails, setCuttingReceiptInwardDetails }) => {

  const { data: sizeList, isLoading: isSizeLoading, isFetching: isSizeFetching } = useGetSizeMasterQuery({ params, });
  const { data: uomList, isLoading: uomLoading, isFetching: uomFetching } = useGetUnitOfMeasurementMasterQuery({ params })
  const { data: colorList, isLoading: colorLoading, isFetching: colorFetching } = useGetColorMasterQuery({ params })

  const handleInputChange = (value, index, field) => {
    const newBlend = structuredClone(cuttingReceiptInwardDetails);
    newBlend[index][field] = value;
    setCuttingReceiptInwardDetails(newBlend);
  };

  const {
    data: cuttingOrderDetails,
    isFetching: isCuttingOrderDetailsFetching,
    isLoading: isCuttingOrderDetailsLoading,
  } = useGetCuttingOrderByIdQuery(cuttingOrderId, { skip: !cuttingOrderId });


  if (uomLoading || uomFetching || colorFetching || colorLoading || !cuttingOrderDetails || !sizeList || isSizeLoading || isSizeFetching) {
    return <tr>
      <td>
        <Loader />
      </td>
    </tr>
  }


  return (
    <fieldset
      disabled={readOnly}
      className="frame rounded-tr-lg rounded-bl-lg rounded-br-lg w-full border
                            border-gray-600 overflow-auto min-h-[180px]"
    >
      <legend className="sub-heading">Cutting Receipt Details</legend>
      <div className={`relative w-full overflow-y-auto p-1`}>
        <table className="table-data border border-gray-500 text-xs table-auto w-full">
          <thead className="bg-blue-200 border border-gray-500 top-0">
            <tr className="border border-gray-500">
              <th className="table-data w-2 text-center">S.no</th>
              <th className="table-data w-24">Color</th>
              <th className="table-data w-20">Size</th>
              <th className="table-data w-20"> Uom</th>
              <th className="table-data w-20">Order Qty</th>
              <th className="table-data w-20">Already Received Qty</th>
              <th className="table-data w-20">Bal To Rec Qty</th>
              <th className="table-data w-20">Order Price</th>
              <th className="table-data w-20">Received Qty</th>
            </tr>
          </thead>
          <tbody className="overflow-y-auto table-data h-full w-full">
            {console.log(cuttingReceiptInwardDetails, "cuttingReceiptInwardDetails")}
            {cuttingReceiptInwardDetails.map((item, index) =>
              <tr key={index} className='py-2 table-row'>
                <td className='table-data   '>
                  {index + 1}
                </td>
                <td className='table-data'>
                  {id ? findFromList(findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "colorId"), colorList.data, "name") : findFromList(item.colorId, colorList.data, "name")}
                </td>
                <td className=' table-data text-right px-1'>
                  {id ? findFromList(findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "sizeId"), sizeList.data, "name") : findFromList(item.sizeId, sizeList.data, "name")}
                </td>
                <td className='  table-data '>
                  {id ? findFromList(findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "uomId"), uomList.data, "name") : findFromList(item.uomId, uomList.data, "name")}
                </td>
                <td className='  table-data text-right px-1'>
                  {id ? findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "orderQty") : item.orderQty}
                </td>
                <td className='  table-data text-right px-1'>
                  <CuttingReceiptAlreadyReceivedQty cuttingOrderDetailsId={id ? item.cuttingOrderDetailsId : item.id} cuttingReceiptInwardDetailsId={id ? item.id : null}
                    setCuttingReceiptInwardDetails={setCuttingReceiptInwardDetails} index={index} />
                </td>
                <td className='  table-data text-right px-1'>
                  {substract(id ? findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "orderQty") : item.orderQty, item.allReadyReceivedQty)}
                </td>
                <td className='  table-data text-right px-1'>
                  {id ? findFromList(item.cuttingOrderDetailsId, cuttingOrderDetails.data.CuttingOrderDetails, "cuttingPrice") : item.cuttingPrice}
                </td>
                <td className='table-data'>
                  <input
                    type="number"
                    onFocus={(e) => e.target.select()}
                    className="text-right rounded py-1 px-1 w-full table-data-input"

                    value={(!item.receivedQty) ? 0 : item.receivedQty}

                    onChange={(e) => {
                      if (!isBetweenRange(0, substract(item.orderQty, item.allReadyReceivedQty), e.target.value)) {
                        toast.info("Inward Qty Cannot be more than balance Qty", { position: 'top-center' })
                        return
                      }
                      handleInputChange(e.target.value, index, "receivedQty")
                    }}
                    onBlur={(e) =>
                      handleInputChange(parseFloat(e.target.value).toFixed(3), index, "receivedQty")
                    }
                  />
                </td>
              </tr>
            )
            }
            {Array.from({ length: 5 - cuttingReceiptInwardDetails.length }).map(i =>
              <tr key={i} className='w-full font-bold h-6 border-gray-400 border table-row'>
                <td className='table-data'> </td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
              </tr>)
            }
          </tbody>
        </table>
      </div>
    </fieldset>
  );
};

export default CuttingReceiptInwardDetails;
