import React from 'react'
import Address from './Address';
import YarnPurchaseOrder from './YarnPurchaseOrder';

import RainDot from "../../../assets/RainDot.png"
import QRCode from "react-qr-code";
import FabricPurchaseOrder from './FabricPurchaseOrder';
import AccessoryPurchaseOrder from './AccessoryPurchaseOrder';
import { useGetPaytermMasterQuery } from "../../../redux/ErpServices/PayTermMasterServices";
import { findFromList, findFromListReturnsItem, getDateFromDateTimeToDisplay } from '../../../Utils/helper';
import secureLocalStorage from 'react-secure-storage';
import {
  useGetBranchQuery, useGetBranchByIdQuery
} from '../../../redux/services/BranchMasterService';
import { useGetPartyQuery } from '../../../redux/ErpServices/PartyMasterServices';
import useTaxDetailsHook from '../../../CustomHooks/TaxHookDetails';
import TaxDetails from './TaxDetails';
import { useGetTermsAndConditionsByIdQuery, useGetTermsAndConditionsQuery } from '../../../redux/services/TermsAndConditionsService';
const numberToText = require('number-to-text')
require('number-to-text/converters/en-in');

export default function Form({ poType, innerRef, poItems, supplierDetails, singleData, poNumber, poDate, payTermId, deliveryType, deliveryToId,
  remarks,
  taxTemplateId, discountType, discountValue }) {

  const branchId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "currentBranchId"
  )
  const companyId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userCompanyId"
  )

  const params = {
    branchId, companyId
  };
  const { data: payTermList } =
    useGetPaytermMasterQuery({ params: { ...params } });
  const { data: branchList } = useGetBranchQuery({ params: { companyId } });
  const { data: supplierList } =
    useGetPartyQuery({ params: { ...params } });

  const { data: termsAndCondition } = useGetTermsAndConditionsQuery({ params: { poType } })

  function getDeliveryDetails() {
    if (deliveryType === "ToSelf") {
      let deliveryObj = findFromListReturnsItem(deliveryToId, branchList?.data ? branchList.data : [])
      if (!deliveryObj) return null
      return { name: deliveryObj.branchName, address: deliveryObj.address }
    } else {
      let deliveryObj = findFromListReturnsItem(deliveryToId, supplierList ? supplierList.data : [])
      if (!deliveryObj) return null
      return { name: deliveryObj.name, address: deliveryObj.address, contactMobile: deliveryObj.contactMobile }
    }
  }
  const deliveryTo = getDeliveryDetails();

  const from = {
    aliasName: "PS TEX",
    name: "PS TEX - GARMENT",
    address: "GS Edifice , 13/1,1st Floor , Bungalow Road,Avinashi - TiruppurRoad,Tiruppur",
    gstNo: "33AAICB7704K",
    panNo: "AAICB7704K",
    mobile: "0424-641601",
    eMail: "pinnaclesystems@gmail.com",
  }

  const { isLoading: isTaxHookDetailsLoading, ...taxDetails } = useTaxDetailsHook({ poItems, taxTypeId: taxTemplateId, discountType, discountValue })


  if (!supplierDetails || !singleData || !supplierList || isTaxHookDetailsLoading || !termsAndCondition) return null

  return (
    <div className="h-[1020px] w-full flex flex-col justify-between border-2 m-0 border-black" id='poPrint' ref={innerRef}>
      <div>

        <div className='flex'>
          <div className='w-1/4 flex items-center justify-center'>
            <img src={RainDot} alt='image' className="h-9 w-9" />
            <h1 className='font-bold text-md text-green-700'>{from.aliasName}</h1>
          </div>
          <div className='text-start p-2 w-full'>
            <div className=' w-full text-center p-1 '>
              <h1 className='font-bold text-green-700 text-md '>{from.name}</h1>
              <h1 className='text-xs'>{from.address}--</h1>
              <h1 className='text-xs'>{from.mobile}</h1>
              <h1 className='text-xs'>PANNO: {from.panNo} / GSTNO: {from.gstNo}</h1>
            </div>
          </div>
        </div>
        <div className='text-center p-1 text-md flex items-center justify-center font-bold text-green-700 w-full'> PURCHASE ORDER</div>
        <div className=''>
          <table className="text-xs border border-gray-500 w-full table-auto ">
            <tbody>
              <tr className='text-xs'>
                <td >PO No : {poNumber}</td>
                <td> PO Date : {getDateFromDateTimeToDisplay(poDate)}</td>
                <td> Payment Terms : {findFromList(payTermId, payTermList.data, "name")}</td>
                <td className='table-data px-14 py-1 w-1/6'>
                  <QRCode value={poNumber} size={80} />
                </td>
              </tr>
            </tbody>
          </table>
        </div>
        <Address deliveryTo={deliveryTo} supplierDetails={supplierDetails} />
        {singleData.transType.toLowerCase().includes("yarn")
          ?
          <YarnPurchaseOrder poItems={poItems} taxDetails={taxDetails} />
          :
          (singleData.transType.toLowerCase().includes("fabric"))
            ?
            <FabricPurchaseOrder poItems={poItems} taxDetails={taxDetails} />
            :
            <AccessoryPurchaseOrder poItems={poItems} taxDetails={taxDetails} />
        }
        <div className='flex justify-end'>
          <table className='border border-gray-500 text-center'>
            <tbody>
              <tr className='border border-gray-500 '><th className='p-2 bg-green-200 text-xs' colSpan={2}>Tax Details</th></tr>
              <TaxDetails items={poItems} taxTemplateId={taxTemplateId} discountType={discountType} discountValue={discountValue} />
              <tr className='border border-gray-500 text-xs '>
                <td className='table-data p-1'>
                  ROUNDOFF
                </td>
                <td className='table-data text-right p-1'>
                  {parseFloat(taxDetails?.roundOffAmount).toFixed(2)}
                </td>
              </tr>
              <tr className='border border-gray-500 text-xs'>
                <td className='table-data p-1 bg-green-200 text-xs'>
                  NET AMOUNT
                </td>
                <td className='table-data p-1 text-xs'>
                  {parseFloat(taxDetails?.netAmount).toFixed(2)}
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
      <div className=' w-full'>
        <div className='w-full '>
          <div className='w-full border border-gray-600 flex items-center'>
            <h1 className='font-bold text-sm'>Amount in words    :
            </h1>
            <span className='text-xs'>
              Rs.{numberToText.convertToText(taxDetails?.netAmount, { language: "en-in", separator: "" })} Only
            </span>
          </div>
          <div className='w-full border border-gray-600 flex items-center'><h1 className='font-bold text-sm'>Remarks : </h1>
            <span className='text-xs'>
              {remarks}
            </span>
          </div>
          <div className='w-full '>
            <h1 className='text-sm w-full font-bold'>Terms and Condition :
            </h1>
            <h1 className='text-xs w-full '>
              {(termsAndCondition.data ? termsAndCondition.data.filter(item => item.isPurchaseOrder).map((value) =>
                <pre key={value.id} className='font-sans'>{value.description}</pre>
              ) : "")}</h1>
          </div>
        </div>
        <div className=''>
          <div className='text-sm text-right px-24 font-bold'>
            For PS-TEX
          </div>
          <div className='border grid grid-rows-1 grid-flow-col p-2 font-bold text-xs '>
            <h1>Prepared By:</h1>
            <h1>Verified By:</h1>
            <h1>Received By:</h1>
            <h1>Approved By :</h1>
          </div>
        </div>
      </div>
    </div>
  )
}

