import React, { useState, useCallback } from 'react';
import { Loader } from '../../../Basic/components';
import secureLocalStorage from "react-secure-storage";
import { useGetStockQuery } from '../../../redux/ErpServices/StockServices';
import { findFromList } from '../../../Utils/helper';
import YarnPoItemSelection from './YarnPoItemSelection';
import FabricPoItemSelection from './FabricPoItemSelection';
import AccessoryPoItemSelection from './AccessoryPoItemSelection';
import { poTypes } from '../../../Utils/DropdownData';
import { LongDropdownInput } from '../../../Inputs';
import { dropDownListObject } from '../../../Utils/contructObject';
import { EMPTY_ICON } from "../../../icons";


import {
  useGetLocationMasterQuery,
} from "../../../redux/ErpServices/LocationMasterServices";
import {
  useGetBranchQuery,
} from '../../../redux/services/BranchMasterService';

const PoItemsSelection = () => {
  const [poType, setPoType] = useState("GreyYarn")
  const [storeId, setStoreId] = useState("")

  const [searchValue, setSearchValue] = useState("");
  const [id, setId] = useState("");
  const [locationId, setLocationId] = useState('');
  const [readOnly, setReadOnly] = useState(false);

  const companyId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userCompanyId"
  )
  const branchId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "currentBranchId"
  )

  const { data: poList, 
  } = useGetStockQuery({ params: { branchId, isGetStock: true } });

  const { data: locationData } = useGetLocationMasterQuery({ params: { branchId }});
  const { data: branchList, isLoading: isBranchLoading, isFetching: isBranchFetching } = useGetBranchQuery({ params: { companyId } });

  let
    filteredPoList = poList ? poList.data.filter(p => { 
       return (storeId ?(p.storeId==storeId && p.itemType===poType) :locationId? (locationId == findFromList(p.storeId, locationData.data, "locationId") && (p.itemType===poType))
          : p.itemType===poType
       )
     }) : []



  const syncFormWithDb = useCallback((data) => {

    if (id) {
      setReadOnly(true);
    } else {
      setReadOnly(false);
    }

    setStoreId(data?.storeId ? data.storeId : "");

    setLocationId(data?.storeId ? (
      locationData.data.find(item => parseInt(item.id) === parseInt(data.storeId))
        ?
        locationData.data.find(item => parseInt(item.id) === parseInt(data.storeId)).locationId
        :
        ""
    ) : "")

  }, [id]);

  const storeOptions = locationData ?
    locationData.data.filter(item => parseInt(item.locationId) === parseInt(locationId)) :
    [];



  if (!branchList || !locationData) return <Loader />


  return (
    <div className=''>
      <div className='w-full h-full  p-2'>
        <h1 className='md:flex md:items-center md:justify-between page-heading p-2 font-bold'>Stock Registry</h1>
        <div className='flex justify-between text-center bg-blue-200 rounded-b-md mb-7 sticky top-0 '>
          <div className='p-2 rounded-lg flex items-center gap-5'>
            <div className='flex gap-10 items-center justify-center md:my-1 px-1 data'>
              <label>Po Type</label>
              <select id='dd' autoFocus name="name" className='h-6 w-40 border border-gray-500 rounded' value={poType} onChange={(e) => setPoType(e.target.value)}>
                {poTypes.map((option, index) => <option key={index} value={option.value} >
                  {option.show}
                </option>)}
              </select>



              <LongDropdownInput name="Location"
                options={branchList ? (dropDownListObject(id ? branchList.data : branchList.data.filter(item => item.active), "branchName", "id")) : []}
                value={locationId}
                setValue={(value) => { setLocationId(value); setStoreId("") }}
                required={true} readOnly={id || readOnly} />
              <LongDropdownInput name="Store"
                options={dropDownListObject(id ? storeOptions : storeOptions.filter(item => item.active), "storeName", "id")}
                value={storeId} setValue={setStoreId} required={true} readOnly={id || readOnly} />
            </div>
          </div>



        </div>
        <div>
          {
            filteredPoList.length !== 0 ?
              <>
                {poType.includes("Yarn") ?
                  <YarnPoItemSelection transtype={poType} poItems={filteredPoList} locationId={locationId} storeId={storeId} />
                  :
                  <>
                    {poType.includes("Fabric") ?

                      <FabricPoItemSelection transtype={poType} poItems={filteredPoList} locationId={locationId} storeId={storeId} />
                      :
                      <AccessoryPoItemSelection transtype={poType} poItems={filteredPoList} locationId={locationId} storeId={storeId}/>
                    }
                  </>
                }
              </>
              :

              <div className="flex justify-center items-center text-blue-900  text-3xl sm:mt-52">
                <p>{EMPTY_ICON} No Data Found...! </p>
              </div>
          }
        </div>
      </div>
    </div>
  )
}

export default PoItemsSelection