import React, { useEffect, useState } from 'react'
import { useGetYarnMasterQuery } from "../../../redux/ErpServices/YarnMasterServices";
import { useGetUnitOfMeasurementMasterQuery } from "../../../redux/ErpServices/UnitOfMeasurementServices";
import secureLocalStorage from 'react-secure-storage';
import { Loader } from '../../../Basic/components';
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { findFromList, getDateFromDateTime } from '../../../Utils/helper';
import { useGetLocationMasterQuery } from '../../../redux/ErpServices/LocationMasterServices';
import {
    useGetBranchQuery,
} from '../../../redux/services/BranchMasterService';
import { useGetProcessQuery } from '../../../redux/ErpServices/processMasterServices';


const YarnPoItemSelection = ({ poItems, transtype, locationId, storeId }) => {
    const [localItems, setLocalItems] = useState([]);

    const [searchFilter, setSearchFilter] = useState([]);

    useEffect(() => {
        setLocalItems(poItems);
    }, [poItems])

    function filterRecords(localItems) {
        let newLocalItems = [...localItems]

        newLocalItems = newLocalItems.filter(item => {
            for (let filter of searchFilter) {
                let fieldName = filter.fieldName
                let searchValue = filter.searchValue
                let objTransformFunc = filter.objTransformFunc
                let itemObj = objTransformFunc(item[fieldName])
                if (!(`${itemObj}`.toLowerCase().includes(searchValue.toLowerCase()))) return false
            }
            return true
        })
        return newLocalItems
    }

    useEffect(() => {
        setLocalItems(prev => filterRecords(prev))
    }, [setLocalItems, searchFilter, poItems])


    const companyId = secureLocalStorage.getItem(
        sessionStorage.getItem("sessionId") + "userCompanyId"
    )

    const params = {
        companyId: secureLocalStorage.getItem(
            sessionStorage.getItem("sessionId") + "userCompanyId"
        ),
    };
    const { data: yarnList, isLoading: yarnListLoading, isFetching: yarnListFetching } = useGetYarnMasterQuery({ params })
    const { data: uomList, isLoading: uomLoading, isFetching: uomFetching } = useGetUnitOfMeasurementMasterQuery({ params })
    const { data: colorList, isLoading: colorLoading, isFetching: colorFetching } = useGetColorMasterQuery({ params })
    const { data: storeList, isLoading: storeLoading, isFetching: storeFetching } = useGetLocationMasterQuery({ params })
    const { data: branchList, isLoading: isBranchLoading, isFetching: isBranchFetching } = useGetBranchQuery({ params });
    const { data: processList, isLoading: isProcessLoading, isFetching: isProcessFetching } = useGetProcessQuery({ params });

    if (yarnListLoading || yarnListFetching || uomFetching || uomLoading || colorFetching || colorLoading || isBranchLoading || isBranchFetching
        || storeFetching || storeLoading || isProcessFetching || isProcessLoading
    ) {
        return <tr>
            <td>
                <Loader />
            </td>
        </tr>
    }

    let count = 1;
    return (
        <div className='border bg-gray-200'>
            <table className='table-fixed border border-gray-500 w-full text-xs'>
                <thead>
                    <tr className='bg-blue-200 border border-gray-500 sticky top-10 '>
                        <th className='text-left table-data border-l-black'>
                            S.no
                        </th>

                        <th className='table-data'>
                            Yarn Name
                        </th>
                        <th className='table-data'>
                            Uom
                        </th>
                        <th className='table-data'>
                            Color
                        </th>
                        <th className='table-data'>
                            Prev. Process
                        </th>
                        <th className='table-data'>
                            Store name
                        </th>
                        <th className='table-data'>
                            Location Name
                        </th>
                        <th className='table-data'>
                            Stock qty
                        </th>
                        <th className='table-data'>
                            Price
                        </th>
                    </tr>
                </thead>
                <tbody>

                    {localItems.map((item, index) =>
                        <tr key={index} className='w-full table-row'>
                            <td className='text-left px-1 table-data shadow-xl'>
                                {count++}
                            </td>
                            <td className='text-left px-1 table-data shadow-xl'>
                                {findFromList(item.itemDetails.yarnId, yarnList.data, "aliasName")}
                            </td>
                            <td className='text-left px-1 table-data shadow-xl'>
                                {findFromList(item.itemDetails.uomId, uomList.data, "name")}
                            </td>
                            <td className='text-left px-1 table-data shadow-xl '>
                                {findFromList(item.itemDetails.colorId, colorList.data, "name")}
                            </td>
                            <td className=' px-1 table-data shadow-xl '>
                                {findFromList(item.processId, processList.data, "name")}
                            </td>
                            <td className='px-1 table-data shadow-xl '>
                                {findFromList(item.storeId, storeList.data, "storeName")}
                            </td>
                            <td className='px-1 table-data shadow-xl '>
                                {findFromList(findFromList(item.storeId, storeList.data, "locationId"), branchList.data, "branchName")}
                            </td>
                            <td className='text-right px-1 table-data shadow-xl '>
                                {(parseFloat(item._sum.qty)).toFixed(3)}
                            </td>
                            <td className='text-right px-1 table-data shadow-xl '>
                                {(parseFloat(item.price)).toFixed(3)}
                            </td>
                        </tr>
                    )
                    }
                </tbody>
            </table>
        </div>

    )
}

export default YarnPoItemSelection