import React, { useEffect } from 'react'
import {
    useGetCuttingOrderDeliveryDetailAllReadyConsumedQtyQuery
} from "../../../redux/ErpServices/CuttingReceiptServices";

const CuttingOrderDeliveryAlreadyConsumedQty = ({ cuttingDeliveryDetailsId,setCuttingReceiptFabricConsumption, index, fabricConsumptionDetailsId}) => {
    const {data, isLoading, isFetching} = useGetCuttingOrderDeliveryDetailAllReadyConsumedQtyQuery({id:cuttingDeliveryDetailsId, fabricConsumptionDetailsId}, {skip:!cuttingDeliveryDetailsId})
    useEffect(()=>{
        if(!data?.data ) return 
        setCuttingReceiptFabricConsumption(prev => {
            if(!prev[index]) return prev
            let newCuttingReceiptFabricConsumption = structuredClone(prev);
            newCuttingReceiptFabricConsumption[index]["allConsumptionQty"] = data.data._sum.consumption ? data.data._sum.consumption : 0
            return newCuttingReceiptFabricConsumption
        })
    }, [cuttingDeliveryDetailsId,fabricConsumptionDetailsId, index, isLoading, isFetching])
    if(isLoading || isFetching || !data?.data) return 1
    return (
        <div>
            {data.data._sum.consumption ? data.data._sum.consumption : 0}
        </div>
    )
}

export default CuttingOrderDeliveryAlreadyConsumedQty
