import React from 'react'
import { useEffect, useState, useRef, useCallback } from "react";
import { useGetPartyQuery, useGetPartyByIdQuery } from "../../../redux/ErpServices/PartyMasterServices"
import moment from "moment/moment";
import { bloodList } from "../../../Utils/DropdownData";
import { AddNewButton } from "../../../Buttons";
import { EMPTY_ICON } from "../../../icons";
import { Loader } from "../../../Basic/components";
import { findFromList, getDateFromDateTime, getDateFromDateTimeToDisplay } from "../../../Utils/helper";
import useGetPoDocId from "../../../CustomHooks/useGetPoDocId";
import PoNumber from '../PoNumber';
import { useGetYarnMasterQuery } from '../../../redux/ErpServices/YarnMasterServices';
import useGetProcessDeliveryDocId from "../../../CustomHooks/useGetProcessDeliveryDocId";

import {
  useGetBranchQuery,
} from '../../../redux/services/BranchMasterService';
import secureLocalStorage from 'react-secure-storage';
import {
  useGetProcessQuery,
} from "../../../redux/ErpServices/processMasterServices";

import {
  useGetPoQuery
} from "../../../redux/ErpServices/PoServices"
import { useGetFabricMasterQuery } from "../../../redux/ErpServices/FabricMasterServices";
import { useGetAccessoryMasterQuery } from "../../../redux/ErpServices/AccessoryMasterServices";
import { useGetAccessoryItemMasterQuery } from "../../../redux/ErpServices/AccessoryItemMasterServices";
import { useGetAccessoryGroupMasterQuery } from "../../../redux/ErpServices/AccessoryGroupMasterServices";
import ProcessInwardNumber from '../ProcessInwardNumber';
import { showEntries } from '../../../Utils/DropdownData';
import { LongDropdownInput, DisabledInput, DropdownInput, DateInput } from "../../../Inputs";
import { useGetProcessInwardQuery } from '../../../redux/ErpServices/ProcessInwardServices';

const ACTIVE = (
  <button className="rounded bg-green-500 border border-green-300 p-1 disabled">
    ACTIVE
  </button>
);
const INACTIVE = (
  <button className="rounded bg-red-500 border border-red-300 p-1 disabled">
    INACTIVE

  </button>
);
const BLOOD_LIST = bloodList;
const MOMENT = moment;
const FIND_FROM_LIST = findFromList;

const ProcessInwardFormReport = ({
  heading,
  tableHeaders,
  tableDataNames,
  tableWidth = "50%",
  loading,
  searchValue,
  setSearchValue,
  onClick,
  processId
}) => {
  const branchId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "currentBranchId"
  )
  const companyId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userCompanyId"
  )
  const params = {
    branchId, companyId
  };
  const { data, isLoading, isFetching } = useGetProcessInwardQuery({ params: { branchId, processId}});

  const { data: supplierList } =
    useGetPartyQuery({ params: { ...params } });
  const [poNo, setPoNo] = useState("");
  const [poDate, setPoDate] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [poType, setPoType] = useState("");
  const [showEntry, setShowEntry] = useState("10")
  const [supplier, setSupplier] = useState("");
  const [id, setId] = useState("");


  if (isLoading || isFetching || !supplierList) {
    return <tr>
      <td>
        <Loader />
      </td>
    </tr>
  }


  return (
    <div className="flex flex-col w-full h-[95%] overflow-auto">
      <div className="md:flex md:items-center md:justify-between page-heading p-2">
        <div className="heading text-center md:mx-10">{heading}</div>
        <div className="flex sub-heading justify-center md:justify-start items-center mr-9">
          <label className="text-white text-sm rounded-md m-1  border-none">Show Entries</label>
          <select value={showEntry}
            onChange={(e) => setShowEntry(e.target.value)} className='h-6 w-40 border border-gray-500 rounded'>
            {showEntries.map((option) => <option value={option.value} >{option.show}</option>)}
          </select>

        </div>
      </div>
      <>
        {loading ? (
          <Loader />
        ) : (
          <>
            {(data?.data ? data?.data : []).length === 0 ? (
              <div className="flex-1 flex justify-center text-blue-900 items-center text-3xl">
                <p>{EMPTY_ICON} No Data Found...! </p>
              </div>
            ) : (
              <div
                className="md:grid md:justify-items-stretch "
                style={{ width: tableWidth }}
              >
                <table className="table-auto text-center">
                  <thead className="border-2 table-header">
                    <tr>
                      {/* <th
                  className="border-2  top-0 stick-bg w-10">
                    S. no.
                </th> */}
                      <th

                        className="border-2  top-0 stick-bg"
                      >
                        <label>Inward.No</label><input
                          type="text"
                          className="text-black h-6 focus:outline-none md:ml-3 border border-gray-400 rounded-lg"
                          placeholder="Search"
                          value={poNo}
                          onChange={(e) => {
                            setPoNo(e.target.value);
                          }}
                        />
                      </th>
                      <th
                        className="border-2  top-0 stick-bg"
                      >
                        <label>Inward.Date</label><input
                          type="text"
                          className="text-black h-6 focus:outline-none md:ml-3 border border-gray-400 rounded-lg"
                          placeholder="Search"
                          value={poDate}
                          onChange={(e) => {
                            setPoDate(e.target.value);
                          }}
                        />
                      </th>
                      <th

                        className="border-2  top-0 stick-bg"
                      >
                        <label>Supplier</label><input
                          type="text"
                          className="text-black h-6 focus:outline-none md:ml-3 border border-gray-400 rounded-lg"
                          placeholder="Search"
                          value={supplier}
                          onChange={(e) => {
                            setSupplier(e.target.value);
                          }}
                        />
                      </th>
                      {/* <th
                        className="border-2  top-0 stick-bg"
                      >
                        <label>Item Type</label><input
                          type="text"
                          className="text-black h-6 focus:outline-none md:ml-3 border border-gray-400 rounded-lg"
                          placeholder="Search"
                          value={poType}
                          onChange={(e) => {
                            setPoType(e.target.value);
                          }}
                        />
                      </th> */}

                      <th className="border-2  top-0 stick-bg">

                        <label>SupplierDc.No</label><input
                          type="text"
                          className="text-black h-6 focus:outline-none md:ml-3 border border-gray-400 rounded-lg"
                          placeholder="Search"
                          value={dueDate}
                          onChange={(e) => {
                            setDueDate(e.target.value);
                          }}
                        />
                      </th>

                    </tr>
                  </thead>
                  <tbody className="border-2">


                    {(data?.data ? data?.data : []).map((dataObj, index) => (
                      <tr
                        key={index}
                        className="border-2 table-row "
                        onClick={() => onClick(dataObj.id)}>
                        {/* <td className='py-1'>{(index + 1) + (dataPerPage * (currentPageNumber - 1))}</td> */}
                        <td className='py-1'>{dataObj.docId}</td>
                        <td className='py-1'>{getDateFromDateTimeToDisplay(dataObj.userInwardDate)} </td>
                        <td className='py-1'>{findFromList(dataObj.ProcessDelivery.supplierId, supplierList.data, "aliasName")}</td>
                        <td className='py-1'>{dataObj.dcNo}</td>
                      </tr>
                    ))}

                  </tbody>
                </table>
              </div>
            )}
          </>
        )}
      </>
    </div>
  )
}

export default ProcessInwardFormReport