// src/components/LedgerReport.js

import React, { useState } from 'react';
import { useGetLedgerQuery } from '../../../redux/ErpServices/Ledger.Services';
import { getDateFromDateTimeToDisplay, params, substract } from '../../../Utils/helper';
import { Loader } from '../../../Basic/components';
import { DateInput, DisabledInput, DropdownInput } from '../../../Inputs';
import { dropDownListObject } from '../../../Utils/contructObject';
import { useGetPartyQuery } from '../../../redux/ErpServices/PartyMasterServices';

const LedgerReport = () => {
    const { companyId } = params
    const [partyId, setPartyId] = useState("");
    const [startDate, setStartDate] = useState("")
    const [endDate, setEndDate] = useState("")

    const { data, isLoading, isFetching } = useGetLedgerQuery({ params: { partyId, startDate, endDate } }, { skip: !partyId || !startDate || !endDate })

    const { data: supplierList, isLoading: isSupplierLoading, isFetching: isSupplierFetching } =
        useGetPartyQuery({ params: { companyId, active: true } });


    const allSuppliers = supplierList ? supplierList.data : []


    if (isLoading || isFetching || isSupplierFetching || isSupplierLoading) return <Loader />


    // Sample ledger data (replace with your actual data)
    const ledgerData = data?.data ? data.data : []

    // Calculate the total credit and debit amounts
    const totalCredit = ledgerData.filter(item => item.EntryType === "PayOut").reduce((total, entry) => total + entry.amount, 0);
    const totalDebit = ledgerData.filter(item => item.EntryType === "Bill").reduce((total, entry) => total + entry.amount, 0);
    const balance = totalCredit + totalDebit + (data?.openingBalance ? data?.openingBalance : 0).toFixed(2)
    return (
        <div className=" w-full p-4 bg-gray-50 ">
            <div>
                <h1 className="text-2xl font-semibold mb-4">Party Ledger Report</h1>
                <div className='grid grid-cols-3 gap-x-16'>
                    <DropdownInput name="Supplier"
                        options={dropDownListObject(allSuppliers, "aliasName", "id")}
                        value={partyId} setValue={setPartyId} required={true} />
                    <DateInput name={"From"} value={startDate} setValue={setStartDate} />
                    <DateInput name={"To"} value={endDate} setValue={setEndDate} />
                </div>
            </div>
            <div className='overflow-auto max-h-[500px]'>
                <table className="table-auto w-full bg-white bg-opacity-90 shadow-md rounded-lg text-xs">
                    <thead className='sticky top-0 bg-gray-50'>
                        <tr>
                            <th className="border px-4 py-1">Date</th>
                            <th className="border px-4 py-1">Bill No</th>
                            <th className="border px-4 py-1">Pay Type</th>
                            <th className="border px-4 py-1"></th>
                            <th className="border px-4 py-1">Bill Value</th>
                            <th className="border px-4 py-1">Paid</th>
                        </tr>
                        <tr>
                            <th></th>
                            <th></th>
                            <th></th>
                            <th className='px-4 py-1'>
                                Opening Balance
                            </th>
                            <th></th>
                            <th colSpan={2} className='text-right  px-4 py-1'>
                                {data?.openingBalance}
                            </th>
                        </tr>
                    </thead>
                    <tbody>
                        {partyId &&
                            ledgerData.map((entry, index) => (
                                <tr key={index}>
                                    <td className="border px-4 py-1">{getDateFromDateTimeToDisplay(entry.createdAt)}</td>
                                    <td className="border px-4 py-1">{entry.partyBillNo}</td>
                                    <td className={`border px-4 py-1 text-right ${entry.EntryType === "PayOut" ? 'text-green-600' : 'text-red-600'}`}>{entry.EntryType === "PayOut" ? (entry?.PayOut?.paymentType ? entry?.PayOut?.paymentType : "") : "Bill"}</td>
                                    <td className="border px-4 py-1"></td>
                                    <td className="border px-4 py-1 text-right text-green-600">{entry.EntryType === "PayOut" ? entry.amount.toFixed(2) : ""}</td>
                                    <td className="border px-4 py-1 text-right text-red-600">{entry.EntryType === "Bill" ? entry.amount.toFixed(2) : ""}</td>
                                </tr>
                            ))
                        }
                        <tr className='font-bold'>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1">Totals</td>
                            <td className="border px-4 py-1 text-right text-green-600">{totalCredit.toFixed(2)}</td>
                            <td className="border px-4 py-1 text-right text-red-600">{totalDebit.toFixed(2)}</td>
                        </tr>
                        <tr className='font-bold sticky bottom-0 bg-gray-50'>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1"></td>
                            <td className="border px-4 py-1"></td>
                            <td colSpan={1} className={`mt-2 text-center`}>
                                Closing Balance
                            </td>
                            <td className={`border px-4 py-1 text-right  `}>{balance}</td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default LedgerReport;
