import React, { useEffect, useState } from 'react';
import { Loader } from '../../../Basic/components';
import secureLocalStorage from "react-secure-storage";
import {
    useGetCuttingOrderQuery,
    useGetCuttingOrderByIdQuery,
    useAddCuttingOrderMutation,
    useUpdateCuttingOrderMutation,
    useDeleteCuttingOrderMutation,
  } from "../../../redux/ErpServices/CuttingOrderServices";
  import {
    useGetPartyQuery,
    useGetPartyByIdQuery,
  } from "../../../redux/ErpServices/PartyMasterServices";
  import { useGetStyleMasterQuery,useGetStyleMasterByIdQuery } from "../../../redux/ErpServices/StyleMasterServices";
  import { findFromList, getDateFromDateTime } from "../../../Utils/helper";

const CuttingOrderFillGrid = ({ setFillGrid ,setCuttingOrderId,styleId}) => {
    const companyId = secureLocalStorage.getItem(
        sessionStorage.getItem("sessionId") + "userCompanyId"
    )
    const branchId = secureLocalStorage.getItem(
        sessionStorage.getItem("sessionId") + "currentBranchId"
    )
    const params = {
        branchId,
        companyId,
      };
    const { data: allData, isLoading, isFetching } = useGetCuttingOrderQuery({ params: { branchId } });
    const { data: supplierList } = useGetPartyQuery({ params: { ...params } });
   
    const { data: styleList, isLoading: isStyleLoading, isFetching: isStyleFetching } = useGetStyleMasterQuery({ params: { companyId } });

    const {
        data: styleDetails,
        isFetching: isStyleDetailsFetching,
        isLoading: isStyleDetailsLoading,
      } = useGetStyleMasterByIdQuery(styleId, { skip: !styleId });

    let count = 1;

    // let filterStyleList=allData.data.filter((element)=>{
    //     return(styleId?element.id==styleId:"") 
      
    // })
    if (!supplierList || !styleList || !allData || !styleDetails) {
        return (
          <tr>
            <td>
              <Loader />
            </td>
          </tr>
        );
      }
    return (
        <div className='w-[1100px] h-[500px] overflow-auto'>{console.log(allData,"styleDetails")}
            <table className="text-xs table-fixed w-full table-">
                <thead>
                    <tr className='bg-blue-200 border border-gray-500 sticky top-0'>
                       
                        <th className="table-data  w-16">Doc.Id</th>
                        <th className="table-data  w-16">Doc. Date</th>
                        <th className="table-data  w-16">Supplier</th>
                        <th className="table-data  w-16">Style</th>
                       
                    </tr>
                </thead>
                <tbody>
                    {allData.data.map((item, index) =>
                        <tr key={index} className='w-full table-row'   onClick={()=>{setCuttingOrderId(item.id); setFillGrid(false)}}>
                           
                            <td className='text-left px-1 table-data shadow-xl'>
                                {item.docId}
                            </td>
                            <td className='text-left px-1 table-data shadow-xl'>
                                {getDateFromDateTime(item.createdAt)}
                            </td>
                            <td className='text-left px-1 table-data shadow-xl'>
                                {findFromList(item.partyId, supplierList.data, "name")}
                            </td>
                           
                            <td className='text-left px-1 table-data shadow-xl '>
                                {findFromList(item.styleId, styleList.data, "name")}
                            </td>
                           
                        </tr>
                    )
                        }
                </tbody>
            </table>
        </div>
    )
}

export default CuttingOrderFillGrid