import React, { useEffect, useState, useRef, useCallback } from "react";
import secureLocalStorage from "react-secure-storage";

import {
  useGetCuttingReceiptQuery,
  useGetCuttingReceiptByIdQuery,
  useAddCuttingReceiptMutation,
  useUpdateCuttingReceiptMutation,
  useDeleteCuttingReceiptMutation,
} from "../../../redux/ErpServices/CuttingReceiptServices";
import { useGetPartyQuery } from "../../../redux/ErpServices/PartyMasterServices";
import FormHeader from "../../../Basic/components/FormHeader";
import FormReport from "../../../Basic/components/FormReportTemplate";
import { toast } from "react-toastify";
import { LongDropdownInput, LongDisabledInput, DropdownInput, TextInput, DateInput, DisabledInput } from "../../../Inputs";
import ReportTemplate from "../../../Basic/components/ReportTemplate";
import { dropDownListObject, } from '../../../Utils/contructObject';
import { useDispatch } from "react-redux";
import { findFromList, getDateFromDateTime, getItemFullNameFromShortCode } from "../../../Utils/helper";
import moment from "moment";
import { Loader } from "../../../Basic/components";
import _ from "lodash";

// import { useReactToPrint } from 'react-to-print';
import PrintFormatYarnDeliveryToKnitting from "../PrintFormat-YarnDeliveryToKnitting"
import {
  useGetLocationMasterQuery,
} from "../../../redux/ErpServices/LocationMasterServices";
import {
  useGetBranchQuery,
} from '../../../redux/services/BranchMasterService';
import { useGetStyleMasterQuery } from "../../../redux/ErpServices/StyleMasterServices";
import Modal from "../../../UiComponents/Modal";
import CuttingReceiptInwardDetails from "./CuttingReceiptInwardDetails";
import CuttingReceiptFormReport from "./CuttingReceiptFormReport";
import {
  useGetCuttingOrderQuery,
  useGetCuttingOrderByIdQuery,
} from "../../../redux/ErpServices/CuttingOrderServices";
import CuttingOrderFillGrid from "../../../ERP/Components/CuttingDelivery/CuttingOrderFillGrid";
import StockSelectionFillGrid from "./StockFillGrid";
import Consolidation from "./Consolidation";
import FabricConsumptionDetails from "./FabricConsumptionDetails";
import { PrintFormatCuttingReceipt } from "..";

const MODEL = "Cutting Receipt";

export default function Form() {

  const componentRef = useRef();
  // const handlePrint = useReactToPrint({
  //   content: () => componentRef.current,
  // });
  const handlePrint = () => {}


  const dispatch = useDispatch()

  const today = new Date()
  const [id, setId] = useState("");
  const [form, setForm] = useState(true);
  const [readOnly, setReadOnly] = useState(false);
  const [locationId, setLocationId] = useState('');
  const [cuttingOrderId, setCuttingOrderId] = useState("");
  const [docId, setDocId] = useState("");
  const [deliveryToId, setDeliveryToId] = useState("")

  const [cuttingReceiptInwardDetails, setCuttingReceiptInwardDetails] = useState([])
  const [cuttingReceiptFabricConsumption, setCuttingReceiptFabricConsumption] = useState([])

  const [storeId, setStoreId] = useState("")

  const [supplierId, setSupplierId] = useState("");

  const [delNo, setDelNo] = useState("")

  const [delDate, setDelDate] = useState(getDateFromDateTime(today))
  const [dueDate, setDueDate] = useState("")

  const [remarks, setRemarks] = useState("");
  const [specialInstructions, setSpecialInstructions] = useState("")
  const [vehicleNo, setVehicleNo] = useState("");

  const [styleId, setStyleId] = useState("");
  const [active, setActive] = useState(true)

  const [formReport, setFormReport] = useState(false);

  const [searchValue, setSearchValue] = useState("");
  const [cuttingOrderFillGrid, setCuttingOrderFillGrid] = useState(false);
  const childRecord = useRef(0);
  const [dcNo, setDcNo] = useState("")

  const branchId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "currentBranchId"
  )
  const userId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userId"
  )
  const companyId = secureLocalStorage.getItem(
    sessionStorage.getItem("sessionId") + "userCompanyId"
  )

  const params = {
    companyId: secureLocalStorage.getItem(
      sessionStorage.getItem("sessionId") + "userCompanyId"
    ),
  };
  const { data: locationData, isLoading: isLocationLoading, isFetching: isLocationFetching } = useGetLocationMasterQuery({ params: { branchId }, searchParams: searchValue });
  const { data: branchList, isLoading: isBranchLoading, isFetching: isBranchFetching } = useGetBranchQuery({ params: { companyId } });
  const { data: styleList, isLoading: isStyleLoading, isFetching: isStyleFetching } = useGetStyleMasterQuery({ params, searchParams: searchValue });
  // const { data: allData, isLoading, isFetching } = useGetCuttingDeliveryQuery({ params: { branchId }, searchParams: searchValue });
  const { data: cuttingOrderList, isLoading: isCuttingOrderLoading, isFetching: isCuttingOrderFetching } = useGetCuttingOrderQuery({ params: { branchId } });
  const { data: supplierList } =
    useGetPartyQuery({ params });




  const { data: allData, isLoading, isFetching } = useGetCuttingReceiptQuery({ params: { branchId }, searchParams: searchValue });
  const {
    data: singleData,
    isFetching: isSingleFetching,
    isLoading: isSingleLoading,
  } = useGetCuttingReceiptByIdQuery(id, { skip: !id });




  const {
    data: cuttingOrderDetails,
    isFetching: isCuttingOrderDetailsFetching,
    isLoading: isCuttingOrderDetailsLoading,
  } = useGetCuttingOrderByIdQuery(cuttingOrderId, { skip: !cuttingOrderId });







  useEffect(() => {
    if (id) return
    if (!cuttingOrderDetails?.data) return
    setCuttingReceiptInwardDetails(cuttingOrderDetails.data.CuttingOrderDetails)
    setCuttingReceiptFabricConsumption(cuttingOrderDetails.data.CuttingDelivery.flatMap(item => item.CuttingDeliveryDetails))
  }, [cuttingOrderDetails, isCuttingOrderDetailsFetching, isCuttingOrderDetailsLoading])


  const [addData] = useAddCuttingReceiptMutation();
  const [updateData] = useUpdateCuttingReceiptMutation();
  const [removeData] = useDeleteCuttingReceiptMutation();

  const getNextDocId = useCallback(() => {
    if (id) return
    if (allData?.nextDocId) {
      setDocId(allData.nextDocId)
    }
  }, [allData, isLoading, isFetching, id])

  useEffect(getNextDocId, [getNextDocId])

  const syncFormWithDb = useCallback((data) => {
    if (id) {
      setReadOnly(true);
    } else {
      setReadOnly(false);
    }
    if (data?.createdAt) setDelDate(moment.utc(data?.createdAt).format("YYYY-MM-DD"));
    if (data?.docId) {
      setDocId(data.docId);
    }
    setSupplierId(data?.supplierId ? data?.supplierId : "");
    setDeliveryToId(data?.deliveryId ? data?.deliveryId : "");
    setLocationId(data?.storeId ? findFromList(data?.storeId, (locationData?.data ? locationData.data : []), "locationId") : "")
    setStoreId(data?.storeId ? data?.storeId : "");
    setVehicleNo(data?.vehicleNo ? data.vehicleNo : "");
    setCuttingReceiptInwardDetails(data?.CuttingReceiptDetails ? data?.CuttingReceiptDetails : []);
    setCuttingOrderId(data?.cuttingOrderId ? data?.cuttingOrderId : "")
    setStyleId(data?.cuttingOrderId ? findFromList(data.cuttingOrderId, cuttingOrderList ? cuttingOrderList.data : [], "styleId") : "");
    setActive(id ? (data?.active ? data.active : false) : true);
    setSpecialInstructions(data?.specialInstructions ? data?.specialInstructions : "")
    setRemarks(data?.remarks ? data?.remarks : "")
    setCuttingReceiptInwardDetails(data?.CuttingReceiptInwardDetails ? data.CuttingReceiptInwardDetails : [] )
    setCuttingReceiptFabricConsumption(data?.CuttingReceiptFabricConsumptionDetails ? data.CuttingReceiptFabricConsumptionDetails : [] )
  }, [id]);

 

  useEffect(() => { if (!id) { setDeliveryToId(supplierId) } }, [supplierId])

  useEffect(() => {
    if (id) {
      syncFormWithDb(singleData?.data);
    } else {
      syncFormWithDb(undefined);
    }
  }, [isSingleFetching, isSingleLoading, id, syncFormWithDb, singleData]);

  const data = {
    delNo,
    delDate,
    supplierId,
    branchId,
    storeId,
    styleId,
    deliveryId: deliveryToId,
    cuttingOrderId,
    cuttingReceiptInwardDetails: cuttingReceiptInwardDetails.map(item => { return { cuttingOrderDetailsId: item.id, receivedQty: item.receivedQty } }),
    cuttingReceiptFabricConsumption: cuttingReceiptFabricConsumption.map(item => { return { cuttingDeliveryDetailsId: item.id, consumption: item.consumption } }),
    id, userId,
  }
  const validateData = (data) => {
    return true
  }

  const handleSubmitCustom = async (callback, data, text) => {
    try {
      let returnData;
      if (text === "Updated") {
        returnData = await callback(data).unwrap();
      } else {
        returnData = await callback(data).unwrap();
      }
      toast.success(text + "Successfully");
      setId("")
      syncFormWithDb(undefined)
      dispatch({
        type: `CuttingOrder/invalidateTags`,
        payload: ['CuttingOrder'],
      });
      dispatch({
        type: `stock/invalidateTags`,
        payload: ['Stock'],
      });
    } catch (error) {
      console.log("handle", error);
    }
  };


  const saveData = () => {

    if (!validateData(data)) {
      toast.info("Please fill all required fields...!", { position: "top-center" })
      return
    }
    if (id) {
      handleSubmitCustom(updateData, data, "Updated");
    } else {
      handleSubmitCustom(addData, data, "Added");
    }
  }

  const deleteData = async () => {
    if (id) {
      if (!window.confirm("Are you sure to delete...?")) {
        return;
      }
      try {
        await removeData(id)
        setId("");
        onNew();
        dispatch({
          type: `po/invalidateTags`,
          payload: ['po'],
        });
        dispatch({
          type: `stock/invalidateTags`,
          payload: ['Stock'],
        });
        toast.success("Deleted Successfully");
      } catch (error) {
        toast.error("something went wrong");
      }
    }
  };

  const handleKeyDown = (event) => {
    let charCode = String.fromCharCode(event.which).toLowerCase();
    if ((event.ctrlKey || event.metaKey) && charCode === "s") {
      event.preventDefault();
      saveData();
    }
  };

  const onNew = () => {
    setId("");
    setForm(true);
    setSearchValue("");
    setReadOnly(false);
    syncFormWithDb(undefined);
    getNextDocId();
  };

  function onDataClick(id) {
    setId(id);
    onNew();
    setForm(true);
  }
  const tableHeaders = ["Po", "Status"]
  const tableDataNames = ['dataObj?.id', 'dataObj.active ? ACTIVE : INACTIVE']


  if (!form)
    return (
      <ReportTemplate
        heading={MODEL}
        tableHeaders={tableHeaders}
        tableDataNames={tableDataNames}
        loading={
          isLocationLoading || isLocationFetching
        }
        setForm={setForm}
        data={allData?.data}
        onClick={onDataClick}
        onNew={onNew}
        searchValue={searchValue}
        setSearchValue={setSearchValue}
      />
    );




  //  if(id) setCuttingReceiptInwardDetails(singleData.data.CuttingReceiptInwardDetails)
  if (isLocationFetching || isLocationLoading || isStyleLoading || isStyleFetching || isCuttingOrderDetailsLoading || isCuttingOrderDetailsFetching) return <Loader />
  const storeOptions = locationData ?
    locationData.data.filter(item => parseInt(item.locationId) === parseInt(locationId)) :
    [];

  const styleOnColor = findFromList(styleId, styleList ? styleList.data : [], "StyleOnColor")
  const colorIds = styleId ? (styleOnColor ? styleOnColor.map(item => parseInt(item.colorId)) : []) : []
  function isColorInStyle(colorId) {
    return styleId ? colorIds.includes(parseInt(colorId)) : true
  }

  return (
    <>
      <Modal isOpen={formReport} onClose={() => setFormReport(false)} widthClass={"px-2 h-[90%] w-[90%]"}>
        <CuttingReceiptFormReport
          heading={MODEL}
          tableDataNames={tableDataNames}
          loading={
            isLoading || isFetching
          }
          allData={allData}
          tableWidth="100%"
          setForm={setForm}
          data={allData?.data}
          onClick={(id) => {
            setId(id);
            setFormReport(false);
          }
          }
          onNew={onNew}
          searchValue={searchValue}
          setSearchValue={setSearchValue}
        />
      </Modal>


      <Modal isOpen={cuttingOrderFillGrid} onClose={() => { setCuttingOrderFillGrid(false) }} widthClass={"bg-gray-300"}>
        <CuttingOrderFillGrid styleId={styleId} setFillGrid={setCuttingOrderFillGrid} setCuttingOrderId={setCuttingOrderId} />
      </Modal>
      <div
        onKeyDown={handleKeyDown}
        className="md:items-start md:justify-items-center grid h-full bg-theme overflow-auto"
      >
        <div className="hidden">
          {/* <PrintFormatCuttingReceipt innerRef={componentRef} /> */}
        </div>
        <div className="flex flex-col frame w-full h-full">
          <FormHeader
            onNew={onNew}
            model={MODEL}
            saveData={saveData}
            setReadOnly={setReadOnly}
            deleteData={deleteData}
            onPrint={id ? handlePrint : null}
            openReport={() => setFormReport(true)}
            childRecord={childRecord.current}
          />
          <div className="flex-1 grid gap-x-2">
            <div className="col-span-3 grid overflow-auto">
              <div className='col-span-3 grid overflow-auto'>
                <div className='mr-1'>
                  <div className={`grid ${formReport ? "grid-cols-12" : "grid-cols-1"} h-full relative overflow-auto`}>
                    <div className={`${formReport ? "col-span-9" : "col-span-1"}`}>
                      <fieldset className='frame rounded-tr-lg rounded-bl-lg rounded-br-lg w-full border border-gray-600 p-1 overflow-auto'>
                        <legend className='sub-heading'>Fabric Delivery To Cutting</legend>
                        <div className='flex flex-col justify-center items-start flex-1 w-full'>
                          <div className="grid grid-cols-5">
                            <DisabledInput name={"Receipt No"} value={docId} />
                            <DateInput name="Receipt Date" value={delDate} type={"date"} required={true} disabled />
                            <DropdownInput name="Location"
                              options={branchList ? (dropDownListObject(id ? branchList.data : branchList.data.filter(item => item.active), "branchName", "id")) : []}
                              value={locationId}
                              setValue={(value) => { setLocationId(value); setStoreId("") }}
                              required={true} readOnly={id || readOnly} />
                            <DropdownInput name="Store"
                              options={dropDownListObject(id ? storeOptions : storeOptions.filter(item => item.active), "storeName", "id")}
                              value={storeId} setValue={setStoreId} required={true} readOnly={id || readOnly} />
                            <DropdownInput name="Supplier" options={supplierList ? (dropDownListObject(id ? supplierList.data : supplierList.data.filter(item => item.active), "aliasName", "id")) : []} value={supplierId} setValue={setSupplierId} required={true} readOnly={id || readOnly} />
                            <DropdownInput name="Delivery To" options={supplierList ? (dropDownListObject(id ? supplierList.data : supplierList.data.filter(item => item.active), "aliasName", "id")) : []} value={deliveryToId} setValue={setDeliveryToId} required={true} readOnly={id || readOnly} />
                            <DropdownInput
                              name="Style"
                              options={dropDownListObject(id ? (styleList ? styleList.data : []) : (styleList ? styleList.data.filter(item => item.active) : []), "name", "id")}
                              value={styleId}
                              setValue={setStyleId}
                              required={true}
                              readOnly={id || readOnly}
                            />
                            <div className="grid grid-cols-12 items-center">
                              <div className="col-span-10">
                                <DisabledInput name={"Cutting Order"} value={cuttingOrderDetails ? cuttingOrderDetails.data.docId : ""} />
                              </div>
                              <button className="p-0.5 text-xs bg-lime-400 rounded hover:bg-lime-600 font-semibold transition hover:text-white -ml-6"
                                onClick={() => {
                                  setCuttingOrderFillGrid(true)
                                }}
                                onKeyDown={(e) => { if (e.key === "Enter") { setCuttingOrderFillGrid(true) } }}
                              >Select</button>
                            </div>
                            <TextInput name="Supplier Dc" type="text" value={dcNo} setValue={setDcNo} required={true} readOnly={readOnly} disabled={(childRecord.current > 0)} />

                          </div>
                        </div>
                      </fieldset>

                      {
                        cuttingOrderDetails &&
                        <CuttingReceiptInwardDetails
                          id={id}
                          cuttingOrderId={cuttingOrderId}
                          cuttingReceiptInwardDetails={cuttingReceiptInwardDetails}
                          setCuttingReceiptInwardDetails={setCuttingReceiptInwardDetails}
                          readOnly={readOnly} />
                      }

                      {cuttingOrderDetails &&
                        <fieldset className='h-[130px] frame rounded-tr-lg rounded-bl-lg rounded-br-lg w-full border border-gray-600 overflow-auto'>
                          <legend className='sub-heading'>Fabric Consumption Details</legend>
                          <FabricConsumptionDetails
                            id={id}

                            cuttingOrderId={cuttingOrderId}
                            cuttingReceiptFabricConsumption={cuttingReceiptFabricConsumption}
                            setCuttingReceiptFabricConsumption={setCuttingReceiptFabricConsumption}
                            readOnly={readOnly} />
                        </fieldset>
                      }

                    </div>

                    <div className={`frame h-[500px] overflow-x-hidden ${formReport ? "block" : "hidden"} col-span-3`}>
                      <FormReport
                        searchValue={searchValue}
                        setSearchValue={setSearchValue}
                        setId={setId}
                        tableHeaders={tableHeaders}
                        tableDataNames={tableDataNames}
                        data={allData?.data ? allData?.data : []}
                        loading={
                          isLocationLoading || isLocationFetching
                        }
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}