import React, { useState } from 'react'
import { MultiSelectDropdown, DateInput } from '../../../Inputs'
import { multiSelectOption } from '../../../Utils/contructObject'
import { useGetPoQuery } from '../../../redux/ErpServices/PoServices';
import { params } from '../../../Utils/helper';
import { useEffect } from 'react';
import { poTypes } from '../../../Utils/DropdownData';

const Parameter = ({ startDate, setStartDate, endDate, setEndDate, filterPoTypes, setFilterPoTypes, filterPos, setFilterPos, filterParties, setFilterParties, partyId, setPartyId, allSuppliers, onClose }) => {
    const [localStartDate, setLocalStartDate] = useState(startDate)
    const [localEndDate, setLocalEndDate] = useState(endDate)
    const [localFilterParties, setLocalFilterParties] = useState(filterParties);
    const [localFilterPos, setLocalFilterPos] = useState([]);
    const [localPartyId, setLocalPartyId] = useState(partyId);
    const [localFilterPoTypes, setLocalFilterPoTypes] = useState(filterPoTypes)

    const [poList, setPoList] = useState([])

    const {
        finYearId,
        branchId
    } = params

    const { data: poData, isLoading, isFetching } = useGetPoQuery({ params: { finYearId, branchId } })

    useEffect(() => {
        if (!poData?.data) return
        let data = poData.data
        // if (localFilterParties.length > 0) {
        //     data = data.filter(item => localFilterParties.findIndex(i => parseInt(i.value) === parseInt(item.supplierId)) !== -1)
        // }
        setPoList(structuredClone(data))
    }, [poData, isLoading, isFetching, localFilterParties, setPoList])


    function handleDone() {
        setStartDate(localStartDate);
        setEndDate(localEndDate);
        setFilterParties(localFilterParties);
        setPartyId(localPartyId);
        setFilterPoTypes(localFilterPoTypes);
        onClose();
    }

    function handleCancel() {
        setLocalStartDate("");
        setLocalEndDate("");
        setLocalFilterParties([]);
        setLocalPartyId("");
        onClose();
    }

    return (
        <div className='w-[900px]'>
            <div className='font-bold w-full text-center'>
                Parameters
            </div>
            <div className='grid items-center justify-center grid-cols-2 gap-x-16 gap-y-5' >
                <DateInput name={"From"} value={localStartDate} setValue={setLocalStartDate} inputClass={"w-[200px]"} />
                <DateInput name={"To"} value={localEndDate} setValue={setLocalEndDate} />
                <MultiSelectDropdown
                    inputClass={"w-[200px] absolute z-50 right-[75px]"}
                    className='relative'
                    name={"PoTypes"}
                    selected={localFilterPoTypes}
                    setSelected={setLocalFilterPoTypes}
                    options={multiSelectOption(poTypes, "show", "value")}
                />
                <MultiSelectDropdown
                    inputClass={"w-[200px] absolute -z-50 right-[75px]"}
                    className='relative'
                    name={"Supplier"}
                    selected={localFilterParties}
                    setSelected={setLocalFilterParties}
                    options={multiSelectOption(allSuppliers, "aliasName", "id")}
                />
                {/* <MultiSelectDropdown
                        inputClass={"w-[200px] absolute z-50 right-[50px]"}
                        className='left-[700px]'
                        name={"Po"}
                        selected={localFilterPos}
                        setSelected={setLocalFilterPos}
                        options={multiSelectOption(poList, "docId", "id")}
                    /> */}
            </div>
            <div className='flex justify-end gap-4 mt-10'>
                <button onClick={handleDone} className='bg-lime-400 hover:bg-lime-600 hover:text-white p-1 px-3 text-sm rounded font-semibold transition'>
                    Done
                </button>
                <button onClick={handleCancel} className='bg-red-400 hover:bg-red-600 hover:text-white p-1 text-sm rounded font-semibold transition'>
                    Cancel
                </button>
            </div>
        </div>
    )
}

export default Parameter
