import React from 'react'
import { findFromList } from '../../../Utils/helper'
import { useGetCompanyByIdQuery, useGetCompanyQuery } from '../../../redux/services/CompanyMasterService';
import secureLocalStorage from 'react-secure-storage';

const Address = ({locationId,branchList,supplierId,supplierList}) => {
    const companyId = findFromList(locationId,branchList,"companyId")
    const params = {
        companyId: secureLocalStorage.getItem(
          sessionStorage.getItem("sessionId") + "userCompanyId"
        ),
      };
  const { data: companyList, isLoading, isFetching } = useGetCompanyQuery({params});

  const { data: singleData, isFetching: isSingleFetching, isLoading: isSingleLoading } = useGetCompanyByIdQuery(companyId, { skip: !companyId });

  

 if(!companyList  || isLoading || isFetching || !singleData || isSingleFetching || isSingleLoading) return null


  return (
    <div className=' '>{console.log(branchList,"branchList",supplierList,"supplierList",companyList,"companyList",singleData,"singleData")}
        <table className="text-xs border border-gray-500 w-full table-auto mt-2">
            <thead className=' top-0 text-left'>
                <tr className='ml-1'>
                    <th className='table-data font-bold w-1/2'>From : {findFromList(locationId,branchList,"branchName")}</th>
                    <th className='table-data font-bold w-1/2'>To : {findFromList(supplierId,supplierList,"name")}  </th>
                </tr>
            </thead>
            <tbody className='overflow-y-auto w-full'>
                <tr>
                    <td className='table-data  p-2 '> 
                   {findFromList(locationId,branchList,"address")} <br></br>
                  {findFromList(locationId,branchList,"contactEmail")}<br></br>
                  {findFromList(locationId,branchList,"contactMobile")}<br></br>
                  <span>Gst.No:  {singleData?.data?.gstNo}</span>  <br></br>
                  <span>Pan.No:  {singleData?.data?.panNo}</span>  <br></br>
                 


                    </td>
                    <td className='table-data  p-2'>
                        {findFromList(supplierId,supplierList,"address")}<br></br>
                        {findFromList(supplierId,supplierList,"email")}<br></br>
                       {findFromList(supplierId,supplierList,"contactMobile")}<br></br>
                    <span>Gst.No:  {findFromList(supplierId,supplierList,"gstNo")}</span>  <br></br>
                    <span>Pan.No: {findFromList(supplierId,supplierList,"panNo")}</span> <br></br>
                        
                        
                          </td>
                </tr>
            </tbody>
        </table>








    </div>
  )
}

export default Address