import React from 'react'
import QRCode from "react-qr-code";
import { useEffect, useState } from 'react'
import { Loader } from '../../../Basic/components';
import { useGetYarnMasterQuery } from "../../../redux/ErpServices/YarnMasterServices";
import secureLocalStorage from 'react-secure-storage';
import { useGetUnitOfMeasurementMasterQuery } from "../../../redux/ErpServices/UnitOfMeasurementServices";
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { findFromList, getDateFromDateTime, getAllowableReturnQty, substract } from '../../../Utils/helper';
import { useGetPartyQuery, useGetPartyByIdQuery } from "../../../redux/ErpServices/PartyMasterServices";

const Address = ({ deliveryTo, supplierDetails }) => {
  if (!deliveryTo || !supplierDetails) return null
  return (
    <div>
      <div className=''>
        <table className="text-xs  w-full p-2 table-auto border border-gray-500">
          <thead className='text-left p-1 ml-1'>
            <tr className=''>
              <th className=' font-bold w-1/2 table-data text-sm'>VENDOR DETAILS : </th>
              <th className=' font-bold text-sm '>DELIVERY TO :</th>
            </tr>
          </thead>
          <tbody>
            <tr className=' text-xs'>
              <td className='p-1 table-data'>
                <h2 className='font-bold text-sm text-green-700'>{supplierDetails.name}</h2>
                <div> {supplierDetails.address} </div>
                <div className=''>Mobile NO :{supplierDetails.contactMobile}</div>
                <div className=''>PAN NO :{supplierDetails.panNo}</div>
                <div className=''>GST NO :{supplierDetails.gstNo}</div>
                <div className=''> EMAIL :{supplierDetails.email}</div>
              </td >
              <div className='mt-0'>
              <td className=''>
                <h2 className='font-bold text-sm text-green-700'>{deliveryTo.name}</h2>
                <div>{deliveryTo.address}</div>
                <div>CONTACT :{deliveryTo.contactMobile}</div>
                {deliveryTo.panNo &&
                  <div className=''>PAN NO :{deliveryTo.panNo}</div>
                }
                {deliveryTo.gstNo &&
                  <div className=''>GST No :{deliveryTo.gstNo}</div>
                }
                {deliveryTo.mail &&
                  <div className=''>EMAIL :{deliveryTo.mail}</div>
                }
              </td>
              </div>
            </tr>
          </tbody>
        </table>
      </div>

    </div>
  )
}


export default Address