import React, { useEffect } from 'react'
import {
    useGetCuttingOrderDetailAllReadyReceivedQtytQuery
} from "../../../redux/ErpServices/CuttingReceiptServices";

const CuttingReceiptAlreadyReceivedQty = ({cuttingOrderDetailsId,setCuttingReceiptInwardDetails, index, cuttingReceiptInwardDetailsId}) => {
    const {data, isLoading, isFetching} = useGetCuttingOrderDetailAllReadyReceivedQtytQuery({id:cuttingOrderDetailsId, cuttingReceiptInwardDetailsId}, {skip:!cuttingOrderDetailsId})
    useEffect(()=>{
        if(!data?.data ) return 
        setCuttingReceiptInwardDetails(prev => {
            if(!prev[index]) return prev
            let newCuttingReceiptInwardDetails = structuredClone(prev);
            newCuttingReceiptInwardDetails[index]["allReadyReceivedQty"] = data.data._sum.receivedQty ? data.data._sum.receivedQty : 0
            return newCuttingReceiptInwardDetails
        })
    }, [cuttingOrderDetailsId, index, isLoading, isFetching])
    if(isLoading || isFetching || !data?.data) return 1
    return (
        <div>
            {data.data._sum.receivedQty ? data.data._sum.receivedQty : 0}
        </div>
    )
}

export default CuttingReceiptAlreadyReceivedQty
