import React, { useEffect, useState } from 'react'
import { useGetFabricMasterQuery } from "../../../redux/ErpServices/FabricMasterServices";
import { useGetUnitOfMeasurementMasterQuery } from "../../../redux/ErpServices/UnitOfMeasurementServices";
import { useGetdesignQuery } from "../../../redux/ErpServices/DesignMasterServices";
import { useGetGaugeQuery } from "../../../redux/ErpServices/GaugeMasterServices";
import { useGetLoopLengthQuery } from "../../../redux/ErpServices/LoopLengthMasterServices";
import { useGetgsmQuery } from "../../../redux/ErpServices/GsmMasterServices";
import { useGetDiaQuery } from "../../../redux/ErpServices/DiaMasterServices";
import secureLocalStorage from 'react-secure-storage';
import { Loader } from '../../../Basic/components';
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { findFromList, isBetweenRange } from '../../../Utils/helper';
import { useGetProcessQuery } from '../../../redux/ErpServices/processMasterServices';

import { DELETE, PLUS } from "../../../icons";
import { toast } from 'react-toastify';
import _ from 'lodash';

const CuttingFabricDeliveryDetails = ({ readOnly, id, openProductionGrid,openStockGrid,cuttingFabricDeliveryDetails,setCuttingFabricDeliveryDetails }) => {
  const params = {
    companyId: secureLocalStorage.getItem(
      sessionStorage.getItem("sessionId") + "userCompanyId"
    ),
  };

  const handleInputChange = (value, index, field) => {
    const newBlend = structuredClone(cuttingFabricDeliveryDetails);
    newBlend[index][field] = value;
    setCuttingFabricDeliveryDetails(newBlend);
  };
  function removeItem(removeItem) {
    setCuttingFabricDeliveryDetails(cuttingFabricDeliveryDetails => {
      let newItems = structuredClone(cuttingFabricDeliveryDetails);
      newItems = newItems.filter(item => !(_.isEqual(item.itemDetails, removeItem.itemDetails)))
      return newItems
    });
  }

  const { data: fabricList, isLoading: fabricListLoading, isFetching: fabricListFetching } = useGetFabricMasterQuery({ params })
  const { data: uomList, isLoading: uomLoading, isFetching: uomFetching } = useGetUnitOfMeasurementMasterQuery({ params })
  const { data: colorList, isLoading: colorLoading, isFetching: colorFetching } = useGetColorMasterQuery({ params })
  const { data: designList, isLoading: designLoading, isFetching: designFetching } = useGetdesignQuery({ params })
  const { data: gaugeList, isLoading: gaugeLoading, isFetching: gaugeFetching } = useGetGaugeQuery({ params })
  const { data: loopList, isLoading: loopLoading, isFetching: loopFetching } = useGetLoopLengthQuery({ params })
  const { data: gsmList, isLoading: gsmLoading, isFetching: gsmFetching } = useGetgsmQuery({ params })
  const { data: diaList, isLoading: diaLoading, isFetching: diaFetching } = useGetDiaQuery({ params })
  const { data: processList, isLoading: isProcessLoading, isFetching: isProcessFetching } = useGetProcessQuery({ params });

  if (fabricListLoading || fabricListFetching || uomFetching || uomLoading || colorFetching || colorLoading || designLoading || designFetching ||
    gaugeLoading || gaugeFetching || loopLoading || loopFetching || gsmLoading || gsmFetching || diaLoading || diaFetching
    || isProcessFetching || isProcessLoading) {
    return <tr>
      <td>
        <Loader />
      </td>
    </tr>
  }
  return (
    <fieldset
      disabled={readOnly}
      className="frame rounded-tr-lg rounded-bl-lg rounded-br-lg w-full border
                            border-gray-600 overflow-auto min-h-[220px]"
    >
      <legend className="sub-heading">Cutting Fabric Delivery Details</legend>
      <div className={`relative w-full overflow-y-auto p-1`}>
        <table className="table-data border border-gray-500 text-xs table-auto w-full">
          <thead className="bg-blue-200 border border-gray-500 top-0">
            <tr className="border border-gray-500">
              <th className="table-data w-2 text-center">S.no</th>
             
              <th className="table-data w-72">Fabric</th>
              <th className="table-data w-20">Color</th>
              <th className="table-data w-20"> Design</th>
              <th className="table-data w-20">Gsm</th>
              <th className="table-data w-20">GG</th>
              <th className="table-data w-20">LL</th>
              <th className="table-data w-20">K.Dia</th>
              <th className="table-data w-20">F.Dia</th>
              <th className="table-data w-20">Uom</th>
             
              <th className="table-data w-20">Stock Qty</th>
              <th className="table-data w-20">Prod. Details</th>


              <th className="table-data w-20">Total Delivery Pcs</th>
              {readOnly ?
                "" :
                <th className='w-20  bg-green-600 text-white'>
                  <div onClick={openStockGrid}
                    className='hover:cursor-pointer w-full h-full flex items-center justify-center'>
                    {PLUS}
                  </div>
                </th>
              }
            </tr>
          </thead>
          <tbody className="overflow-y-auto table-data h-full w-full">{console.log(cuttingFabricDeliveryDetails,"cuttingFabricDeliveryDetails")}
            {cuttingFabricDeliveryDetails.map((item, index) =>
              <tr key={index} className='py-2 table-row'>
                <td className='  table-data   shadow-xl'>
                  {index + 1}
                </td>
                {/* <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.prevProcessId : item.processId, processList.data, "name")}
                </td> */}
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.fabricId : item.itemDetails.fabricId, fabricList.data, "aliasName")}
                </td>
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ?  item.colorId : item.itemDetails.colorId, colorList.data, "name")}
                </td>
                <td className='   table-data  shadow-xl'>
                  {findFromList(id ? item.designId :item.itemDetails.designId, designList.data, "name")}
                </td>
                <td className='   table-data  shadow-xl'>
                  {findFromList(id ? item.gaugeId :item.itemDetails.gaugeId, gaugeList.data, "name")}
                </td>
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.loopLengthId : item.itemDetails.loopLengthId, loopList.data, "name")}
                </td>
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.gsmId : item.itemDetails.gsmId, gsmList.data, "name")}
                </td>
                <td className='   table-data  shadow-xl'>
                  {findFromList(id ? item.kDiaId : item.itemDetails.kDiaId, diaList.data, "name")}
                </td>
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.fDiaId : item.itemDetails.fDiaId, diaList.data, "name")}
                </td>
                <td className='  table-data   shadow-xl'>
                  {findFromList(id ? item.uomId : item.itemDetails.uomId, uomList.data, "name")}
                </td>
               
                <td className=' table-data  text-right'>
                  {(id ? item.stockQty : item._sum.qty)}
                </td>
                
                {readOnly ?
                "" :
                <td className='w-20 bg-green-600 text-white'>
                  <div onClick={openProductionGrid}
                    className='hover:cursor-pointer w-full h-full  flex  items-center justify-center'>
                     {PLUS}
                  </div>
                </td>
              }
              
              <td className=' table-data  text-right'>
                  
                </td>
               
                {!readOnly &&
                  <td className='table-data w-12'>
                    <div tabIndex={-1} onClick={() => removeItem(item)} className='flex justify-center px-2 py-1.5 items-center cursor-pointer bg-gray-300'>
                      {DELETE}
                    </div>
                  </td>
                }
              
               
              </tr>
            )
            }
            {Array.from({ length: 14 - cuttingFabricDeliveryDetails.length }).map(i =>
              <tr key={i} className='w-full font-bold h-6 border-gray-400 border table-row'>
                <td className='table-data'>
                </td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data    "></td>
                <td className="table-data    "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                <td className="table-data   "></td>
                
                {!readOnly
                  &&
                  <td className="table-data   "></td>
                }
                
                
                {!readOnly
                  &&
                  <td className="table-data   "></td>
                }
                 {readOnly
                  &&
                  <td className="table-data   "></td>
                }
                
              </tr>)
            }
          </tbody>
        </table>
      </div>
    </fieldset>
  );
};

export default CuttingFabricDeliveryDetails;
