import { useGetFabricMasterQuery } from '../../../redux/ErpServices/FabricMasterServices';
import React, { useCallback, useEffect, useState } from 'react'
import { useGetColorMasterQuery } from '../../../redux/ErpServices/ColorMasterServices';
import { useGetdesignQuery } from '../../../redux/ErpServices/DesignMasterServices';
import { useGetGaugeQuery } from '../../../redux/ErpServices/GaugeMasterServices';
import { useGetLoopLengthQuery } from '../../../redux/ErpServices/LoopLengthMasterServices';
import { useGetgsmQuery } from '../../../redux/ErpServices/GsmMasterServices';
import { useGetDiaQuery } from '../../../redux/ErpServices/DiaMasterServices';
import { useGetUnitOfMeasurementMasterQuery } from '../../../redux/ErpServices/UnitOfMeasurementServices';
import { Loader } from '../../../Basic/components';
import { findFromList, params, substract } from '../../../Utils/helper';
import { useGetCuttingDeliveryQuery } from '../../../redux/ErpServices/CuttingDeliveryServices';

import { VIEW } from '../../../icons';

import Modal from '../../../UiComponents/Modal';
import LossReasonBreakup from './LossReasonBreakup';
import {
    useGetCuttingOrderQuery,
    useGetCuttingOrderByIdQuery,
  } from "../../../redux/ErpServices/CuttingOrderServices";
import CuttingReceiptAlreadyReceivedQty from './CuttingOrderDeliveryDetailAllReadyConsumedQty';
import CuttingOrderDeliveryAlreadyConsumedQty from './CuttingOrderDeliveryDetailAllReadyConsumedQty';


const FabricConsumptionDetails = ({id,cuttingOrderId, cuttingReceiptFabricConsumption, setCuttingReceiptFabricConsumption, readOnly }) => {
    const [currentSelectedIndex, setCurrentSelectedIndex] = useState("")

    const handleInputChange = (value, index, field) => {
        const newBlend = structuredClone(cuttingReceiptFabricConsumption);
        newBlend[index][field] = value;
        setCuttingReceiptFabricConsumption(newBlend);
    };

console.log(id,"id")
    const {
        data: cuttingOrderDetails,
        isFetching: isCuttingOrderDetailsFetching,
        isLoading: isCuttingOrderDetailsLoading,
      } = useGetCuttingOrderByIdQuery(cuttingOrderId, { skip: !cuttingOrderId });
     

     const cuttingDeliveryDetails=cuttingOrderDetails? cuttingOrderDetails.data.CuttingDelivery.flatMap(item => item.CuttingDeliveryDetails):[]
    
    const { data: fabricList } =
        useGetFabricMasterQuery({ params });

    const { data: colorList } =
        useGetColorMasterQuery({ params });

    const { data: designList } =
        useGetdesignQuery({ params });

    const { data: gaugeList } =
        useGetGaugeQuery({ params });

    const { data: loopLengthList } =
        useGetLoopLengthQuery({ params });

    const { data: gsmList } =
        useGetgsmQuery({ params });

    const { data: diaList } =
        useGetDiaQuery({ params });

    const { data: uomList } =
        useGetUnitOfMeasurementMasterQuery({ params });

    const { data: cuttingDeliveryList } =
        useGetCuttingDeliveryQuery({ params });


    if (!fabricList || !colorList || !uomList || !gaugeList || !designList || !gsmList || !loopLengthList || !diaList || !cuttingDeliveryList || !cuttingOrderDetails) return <Loader />


    return (
        <>
            <Modal isOpen={Number.isInteger(currentSelectedIndex)} onClose={() => setCurrentSelectedIndex("")}>
                <LossReasonBreakup setCurrentSelectedIndex={setCurrentSelectedIndex} currentIndex={currentSelectedIndex}
                    cuttingReceiptFabricConsumption={cuttingReceiptFabricConsumption}
                    setCuttingReceiptFabricConsumption={setCuttingReceiptFabricConsumption} />
            </Modal>
            <div className={`relative w-full overflow-y-auto py-1`}>
                <table className="border border-gray-500 text-xs table-auto w-full">
                    <thead className='bg-blue-200 top-0'>
                        <tr className='h-8'>
                            <th className=' table-data '>
                                S.no
                            </th>
                            <th className=' table-data w-52'>
                                Del Dc.no
                            </th>
                            <th className='table-data w-80'>
                                Fabric Name
                            </th>
                            <th className=' table-data w-20'>
                                Color
                            </th>
                            <th className='table-data w-20'>
                                Design
                            </th>
                            <th className='table-data'>
                                Gauge
                            </th>
                            <th className='table-data'>
                                LL
                            </th>
                            <th className='table-data'>
                                Gsm
                            </th>
                            <th className='table-data'>
                                K-Dia
                            </th>
                            <th className='table-data'>
                                F-Dia
                            </th>
                            <th className='table-data'>
                                Uom
                            </th>
                            <th className='table-data '>
                                Del Qty
                            </th>
                            <th className='table-data'>
                                Alr.Consumption.Qty
                            </th>
                            <th className="table-data w-16">
                                Bal Qty
                            </th>
                            <th className="table-data w-24">
                                Consumption Qty
                            </th>
                            {/* <th className="table-data w-20">Loss Reason</th> */}
                        </tr>
                    </thead>
                    <tbody className='overflow-y-auto border border-gray-600 h-full w-full'>
                        {cuttingReceiptFabricConsumption.map((item, index) => (
                            <tr key={index} className="w-full table-row">
                                <td className='text-left px-1 table-data shadow-xl '>
                                    {index + 1}
                                </td>
                                <td className='text-left px-1 table-data shadow-xl '>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"cuttingDeliveryId"),cuttingDeliveryList.data, "docId"):findFromList(item.cuttingDeliveryId, cuttingDeliveryList.data, "docId")}
                                </td>
                                <td className='text-left px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"fabricId"),fabricList.data, "aliasName"):findFromList(item.fabricId, fabricList.data, "aliasName")}
                                </td>
                                <td className='text-left  table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"colorId"),colorList.data, "name"):findFromList(item.colorId, colorList.data, "name")}
                                </td>
                                <td className='text-left px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"designId"),designList.data, "name"):findFromList(item.designId, designList.data, "name")}
                                </td>
                                <td className='text-right px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"gaugeId"),gaugeList.data, "name"):findFromList(item.gaugeId, gaugeList.data, "name")}
                                </td>
                                <td className='text-right px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"loopLengthId"),loopLengthList.data, "name"):findFromList(item.loopLengthId, loopLengthList.data, "name")}
                                </td>
                                <td className='text-right px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"gsmId"),gsmList.data, "name"):findFromList(item.gsmId, gsmList.data, "name")}
                                </td>
                                <td className='text-right px-1  table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"kDiaId"),diaList.data, "name"):findFromList(item.kDiaId, diaList.data, "name")}
                                </td>
                                <td className='text-right px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"fDiaId"),diaList.data, "name"):findFromList(item.fDiaId, diaList.data, "name")}
                                </td>
                                <td className='text-right px-1 table-data shadow-xl'>
                                    {id?findFromList(findFromList(item.cuttingDeliveryDetailsId,cuttingDeliveryDetails,"uomId"),uomList.data, "name"):findFromList(item.uomId, uomList.data, "name")}
                                </td>
                                <td className=' px-1 table-data shadow-xl text-right'>
                                    {item.issueQty}
                                </td>
                                <td className=' table-data '>
                                    <CuttingOrderDeliveryAlreadyConsumedQty cuttingDeliveryDetailsId={id ? item.id :item.cuttingDeliveryDetailsId} 
                                    setCuttingReceiptFabricConsumption={setCuttingReceiptFabricConsumption} index={index} fabricConsumptionDetailsId={id ? item.id : null} />
                                </td>
                                <td className='  table-data '>
                                    {substract(item.issueQty, item.allConsumptionQty)}
                                </td>
                                <td className=' table-data '>
                                    <input
                                        type="number"
                                        onFocus={(e) => e.target.select()}
                                        className="text-right rounded py-1 px-1 w-full table-data-input"
                                        value={(!item.consumption) ? 0 : item.consumption}
                                        readOnly={readOnly}
                                        onChange={(e) => {
                                            handleInputChange(e.target.value, index, "consumption")
                                        }
                                        }
                                        onBlur={(e) =>
                                            handleInputChange(parseFloat(e.target.value).toFixed(3), index, "consumption")
                                        }
                                    />
                                </td>
                                {/* <td className='table-data'>
                                    <button
                                        className="text-center rounded py-1 w-20"
                                        onKeyDown={(e) => {
                                            if (e.key === "Enter") {
                                                setCurrentSelectedIndex(index);
                                            }
                                        }}
                                        onClick={() => {

                                            setCurrentSelectedIndex(index)
                                        }}>
                                        {VIEW}
                                    </button>
                                </td> */}
                            </tr>
                        ))}
                        {Array.from({ length: 2 - cuttingReceiptFabricConsumption.length }).map(i =>
                            <tr className='w-full font-bold h-6 border-gray-400 border table-row'>
                                <td className='table-data'>
                                </td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data"></td>
                                <td className="table-data   "></td>
                                <td className="table-data   "></td>

                            </tr>)
                        }

                    </tbody>
                </table>
            </div>
        </>
    )
}

export default FabricConsumptionDetails