import React from 'react'
import Address from './Address';
import FabricProgram from './FabricProgram';
import RawMaterialYarn from './RawMaterialYarn';
import { findFromList } from '../../../Utils/helper'
import YarnProgram from './YarnProgram';
import FabricRawMaterial from './FabricRawMaterial';
import { useGetProcessQuery } from '../../../redux/ErpServices/processMasterServices';
import secureLocalStorage from 'react-secure-storage';
import { useGetProcessDeliveryByIdQuery } from '../../../redux/ErpServices/ProcessDeliveryServices';

export default function Form({ id, innerRef, locationId, branchList, supplierId, supplierList, processDocId, 
  delDate, processId, programDetails }) {
  const params = {
    companyId: secureLocalStorage.getItem(
      sessionStorage.getItem("sessionId") + "userCompanyId"
    ),
  };
  const { data: processList, isLoading: isProcessLoading, isFetching: isProcessFetching } = useGetProcessQuery({ params });

  const {
    data: singleData,
    isFetching: isSingleFetching,
    isLoading: isSingleLoading,
  } = useGetProcessDeliveryByIdQuery({id:id}, { skip: !id });

  const fabricData = [
    {
      fabricName: "INTERLOCK( 100%COTTON )",
      color: "GREY",
      design: "SOLID ",
      gsm: "210",
      gg: "24",
      ll: "30.5",
      kDia: "32T",
      fDia: "32T",
      uom: "KGS",
      progQty: "0.350",

    }
  ]
  const fabricTotal = 678.00;

  const yarnData = [
    {
      yarnName: "INTERLOCK( 100%COTTON )",
      color: "GREY",
      uom: "KGS",
      cones: "0",
      bags: "7",
      issQty: "0.350",

    }
  ]
  const yarnTotal = 678.00;
  const rawMaterialName = processId ? (findFromList(processId, processList.data, "io")).toString().split("_").at(0) : ""
  const processName = processId ? (findFromList(processId, processList.data, "io")).toString().split("_").at(1) : ""
  console.log(singleData , isSingleFetching, isSingleLoading, processList, isProcessFetching, isProcessLoading, "process" );
  if (!singleData?.data || isSingleLoading || isSingleFetching || !processList?.data || isProcessLoading || isProcessFetching) return null

  return (
    <div className="h-1/2 overflow-auto p-2" ref={innerRef} >
      <div className='border border-gray-600'>
        {/* <div className='flex h-16 gap-16 px-9 py-3'>
        <div className='flex'>
        <img src={RainDot} alt='image' className="h-12 w-12"/>
      <h1 className='font-bold text-2xl'>RainDot</h1>
      </div> */}
        <div className='text-center w-full'>
          <h1 className='m-2 font-bold'>YARN DELIVERY TO KNITTING</h1>
        </div>
        {/* </div> */}
        <Address locationId={locationId} branchList={branchList} supplierId={supplierId} supplierList={supplierList} />
        <div className='grid grid-rows-1 grid-flow-col gap-1 mt-1 p-1 font-bold text-xs border-b border-gray-500'>
          <div> DC NO : {processDocId}</div>
          <div>DATE: {delDate}</div>
          <div>PROCESS : {findFromList(processId, processList.data, "name")}</div>
        </div>
        {processName?.includes("F")
          ?
          <FabricProgram fabricTotal={fabricTotal} programDetails={programDetails} />
          :
          <YarnProgram fabricTotal={fabricTotal} programDetails={programDetails} />
        }
        {rawMaterialName?.includes("F")
          ?
          <FabricRawMaterial yarnData={yarnData} yarnTotal={yarnTotal} programDetails={programDetails} />
          :
          <RawMaterialYarn yarnData={yarnData} yarnTotal={yarnTotal} programDetails={programDetails} />
        }
        <div className='border flex justify-between p-1 gap-x-2 font-bold text-xs mt-3 border border-gray-500 w-full'>
          <h1>VECHICLE NO: {singleData?.data?.vehicleNo}  </h1>
          {/* <h1>INVOICE TO:  {findFromList(supplierId,supplierList,"name")}</h1> */} 
          <h1 className='text-end'>REMARKS:   {singleData?.data?.remarks}       </h1>
          {/* <h1>FOLLOWERS :</h1> */}
        </div>
        <div className='text-sm text-right px-44 font-bold text-xs mt-3'>
          {findFromList(locationId, branchList, "branchName")}
        </div>
        <div className='border grid grid-rows-1 grid-flow-col p-2 mt-5 font-bold text-xs'>
          <h1>Prepared By:</h1>
          <h1>Verified By:</h1>
          <h1>Received By:</h1>
          <h1>Approved By :</h1>
        </div>
      </div>
    </div>

  )
}

